# Look at agent errors and tool failures from session transcripts
cat > /tmp/agent_errors.py << 'PYEOF'
import json, glob, collections
from pathlib import Path

# Sample agent sessions
files = sorted(set(glob.glob(str(Path.home())+'/.claude-account-*/projects/*schema-semantic*claude-sessions-agent-*/*.jsonl')))
seen = set()
unique_files = []
for f in files:
    b = Path(f).name
    if b not in seen:
        seen.add(b)
        unique_files.append(f)
print(f'Unique agent session files: {len(unique_files)}')

# Look for errors in tool results
error_count = 0
error_samples = []
tool_uses = collections.Counter()
for f in unique_files[:50]:  # sample
    with open(f) as fh:
        for line in fh:
            if '"is_error"' in line and ':true' in line.replace(' ',''):
                try:
                    o = json.loads(line)
                    content = o.get('message', {}).get('content', [])
                    if isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'tool_result' and c.get('is_error'):
                                error_count += 1
                                cc = c.get('content', '')
                                if isinstance(cc, list):
                                    for ci in cc:
                                        if isinstance(ci, dict) and ci.get('type') == 'text':
                                            err_text = ci.get('text','')[:300]
                                            ts = o.get('timestamp','')[:16]
                                            error_samples.append((ts, err_text))
                                            break
                                else:
                                    error_samples.append((o.get('timestamp','')[:16], str(cc)[:300]))
                except: continue
            if '"type":"tool_use"' in line:
                try:
                    o = json.loads(line)
                    content = o.get('message', {}).get('content', [])
                    if isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'tool_use':
                                tool_uses[c.get('name','?')] += 1
                except: continue

print(f'Tool errors in sampled agent sessions: {error_count}')
print()
print('Sample 12 errors:')
import random
samples = random.sample(error_samples, min(12, len(error_samples))) if error_samples else []
for ts, err in samples:
    print(f'[{ts}] {err}')
    print('---')

print()
print('Top tools in agent sessions:')
for t, c in tool_uses.most_common(20):
    print(f'  {c:6d} | {t}')
PYEOF
